     * @param      string $toType   One of the class type constants
     * @return string          translated name of the field.
     * @throws PropelException - if the specified name could not be found in the fieldname mappings.
     */
    public static function translateFieldName($name, $fromType, $toType)
    {
        $toNames = ComRecibidaPeer::getFieldNames($toType);
        $key = isset(ComRecibidaPeer::$fieldKeys[$fromType][$name]) ? ComRecibidaPeer::$fieldKeys[$fromType][$name] : null;
        if ($key === null) {
            throw new PropelException("'$name' could not be found in the field names of type '$fromType'. These are: " . print_r(ComRecibidaPeer::$fieldKeys[$fromType], true));
        }

        return $toNames[$key];
    }

