                $e = new PropelException("Invalid value passed to removeInstanceFromPool().  Expected primary key or ComRecibida object; got " . (is_object($value) ? get_class($value) . ' object.' : var_export($value,true)));
                throw $e;
            }

            unset(ComRecibidaPeer::$instances[$key]);
        }
    } // removeInstanceFromPool()

