        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseComRecibidaPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ComRecibidaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ComRecibidaPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = ComRecibidaPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ComRecibidaPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined ComEnviada rows

                $key2 = ComEnviadaPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = ComEnviadaPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = ComEnviadaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    ComEnviadaPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (ComRecibida) to the collection in $obj2 (ComEnviada)
                $obj2->addComRecibida($obj1);

            } // if joined row is not null

                // Add objects for joined AsuntoRecibida rows

                $key3 = AsuntoRecibidaPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = AsuntoRecibidaPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = AsuntoRecibidaPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    AsuntoRecibidaPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (ComRecibida) to the collection in $obj3 (AsuntoRecibida)
                $obj3->addComRecibida($obj1);

