    public static function getTableMap()
    {
        return Propel::getDatabaseMap(ComRecibidaPeer::DATABASE_NAME)->getTable(ComRecibidaPeer::TABLE_NAME);
    }

    /**
     * Add a TableMap instance to the database for this peer class.
     */
    public static function buildTableMap()
    {
      $dbMap = Propel::getDatabaseMap(BaseComRecibidaPeer::DATABASE_NAME);
      if (!$dbMap->hasTable(BaseComRecibidaPeer::TABLE_NAME)) {
        $dbMap->addTableObject(new \ComRecibidaTableMap());
      }
    }

